319	// TestTransferBatchSaveFailureSameRegistry 覆盖核心场景：保存失败后调用者
320	// 继续使用同一个已打开的登记册，全部状态停留在整批之前；保存条件恢复后
321	// 用原请求号重提完整执行一次。
322	func TestTransferBatchSaveFailureSameRegistry(t *testing.T) {
323		r := mustCreate(t, tempDir(t))
324		seedBatchSaveFailureWorld(t, r)
