383		replay, err := r.IssueBatch(req)
384		if err != nil {
385			t.Fatalf("replay after state changes: %v", err)
386		}
387		if !replay.Replayed {
388			t.Fatal("should be Replayed")
389		}
390		for i := range first.Items {
391			if replay.Items[i] != first.Items[i] {
392				t.Errorf("item %d: replay %+v != first %+v", i, replay.Items[i], first.Items[i])
393			}
