544	// 并发整批提交同一请求只发行一次。
545	func TestIssueBatchConcurrentSameRequest(t *testing.T) {
546		r := mustCreate(t, tempDir(t))
547		setupBatchWorld(t, r)
548		req := batchReq("rb1", be("i1", "bob"), be("i2", "carol"))
549	
550		const n = 8
551		var wg sync.WaitGroup
552		errs := make([]error, n)
553		results := make([]IssueBatchResult, n)
554		for i := 0; i < n; i++ {
555			wg.Add(1)
556			go func(i int) {
557				defer wg.Done()
558				res, err := r.IssueBatch(req)
559				results[i], errs[i] = res, err
560			}(i)
561		}
562		wg.Wait()
563		for i := range errs {
564			if errs[i] != nil {
565				t.Fatalf("goroutine %d: %v", i, errs[i])
566			}
567			if len(results[i].Items) != 2 {
568				t.Fatalf("goroutine %d: %+v", i, results[i])
569			}
570		}
571		// 只发行一次：历史各一条。
572		for _, id := range []string{"i1", "i2"} {
573			hist, err := r.History(id)
574			if err != nil {
575				t.Fatal(err)
576			}
577			if len(hist) != 1 {
