583	// 不同请求与单件发行争用同一编号时，最多一个请求占用该编号。
584	func TestIssueBatchConcurrentIDContention(t *testing.T) {
585		r := mustCreate(t, tempDir(t))
586		setupBatchWorld(t, r)
587	
588		const n = 6
589		var wg sync.WaitGroup
590		errs := make([]error, n)
591		for i := 0; i < n; i++ {
592			wg.Add(1)
593			go func(i int) {
594				defer wg.Done()
595				if i%2 == 0 {
596					_, errs[i] = r.IssueBatch(batchReq(fmt.Sprintf("rb-%d", i), be("hot", "bob")))
597				} else {
598					req := issueReq("hot", "bob")
599					req.RequestID = fmt.Sprintf("rs-%d", i)
600					_, errs[i] = r.Issue(req)
601				}
602			}(i)
603		}
604		wg.Wait()
605		succeeded, alreadyExists := 0, 0
606		for i, err := range errs {
607			switch {
608			case err == nil:
609				succeeded++
610			case errors.Is(err, ErrAlreadyExists):
611				alreadyExists++
612			default:
613				t.Fatalf("goroutine %d: unexpected err %v", i, err)
614			}
615		}
616		if succeeded != 1 || alreadyExists != n-1 {
617			t.Fatalf("succeeded = %d, alreadyExists = %d, want 1 and %d", succeeded, alreadyExists, n-1)
618		}
619		hist, err := r.History("hot")
620		if err != nil {
621			t.Fatal(err)
622		}
623		if len(hist) != 1 {
624			t.Fatalf("hot issued %d times", len(hist))
625		}
626	}
